    "wiki.validator.title": { it: "Validatore", en: "Validator" },
    "wiki.validator.p1": { it: "Il Validatore (icona spunta nella tab destra) controlla automaticamente la storia per errori comuni prima dell'esportazione.", en: "The Validator (check icon in the right tab) automatically checks the story for common errors before export." },
