    "wiki.llm.workflow.title": { it: "Workflow tipico", en: "Typical workflow" },
    "wiki.llm.wf1": { it: "Scrivi il copione della storia in un documento di testo.", en: "Write the story script in a text document." },
    "wiki.llm.wf2": { it: "Usa T01 per generare i post dal copione.", en: "Use T01 to generate posts from the script." },
    "wiki.llm.wf3": { it: "Usa T02-T04 per espandere didascalie, commenti e hashtag.", en: "Use T02-T04 to expand captions, comments and hashtags." },
