    "wiki.loc.title": { it: "Localizzazione", en: "Localization" },
    "wiki.loc.p1": { it: "La localizzazione (icona globe nella tab destra) ti permette di tradurre l'intera storia in piu lingue. Story Forge supporta IT, EN, ES, DE e FR con motori LLM e Machine Translation.", en: "Localization (globe icon in the right tab) lets you translate the entire story into multiple languages. Story Forge supports IT, EN, ES, DE, and FR with LLM and Machine Translation engines." },
    "wiki.loc.how.title": { it: "Come funziona", en: "How it works" },
    "wiki.loc.s1": { it: "Seleziona la lingua di destinazione dalla lista.", en: "Select the target language from the list." },
    "wiki.loc.s2": { it: "Scegli il motore di traduzione (MT o LLM).", en: "Choose the translation engine (MT or LLM)." },
    "wiki.loc.s3": { it: "Clicca Traduci per tradurre tutto o singole sezioni.", en: "Click Translate to translate everything or individual sections." },
    "wiki.loc.s4": { it: "Rivedi e correggi le traduzioni generate.", en: "Review and correct the generated translations." },
    "wiki.loc.s5": { it: "Ripeti per ogni lingua di destinazione.", en: "Repeat for each target language." },
    "wiki.loc.s6": { it: "Le traduzioni vengono salvate nel file story.json separato per lingua.", en: "Translations are saved in a separate story.json file per language." },
