    "wiki.loc.eng.llm": { it: "LLM - piu lenta, richiede API key, qualita superiore", en: "LLM - slower, requires API key, higher quality" },
    "wiki.loc.mirror.title": { it: "Mirror Classes", en: "Mirror Classes" },
    "wiki.loc.mirror.p1": { it: "Le Mirror Classes permettono di tradurre automaticamente campi specifici del profilo social (nome, handle, bio) in base alla lingua selezionata.", en: "Mirror Classes allow automatic translation of specific social profile fields (name, handle, bio) based on the selected language." },
    "wiki.loc.mirror.classes.title": { it: "Classi disponibili", en: "Available classes" },
    "wiki.loc.mirror.a.beh": { it: "Classe A: traduce il campo in base alla lingua corrente", en: "Class A: translates the field based on the current language" },
    "wiki.loc.mirror.a.ex": { it: "Esempio: nome it=Marco, en=Mark, es=Marco, de=Mark, fr=Marc", en: "Example: name it=Marco, en=Mark, es=Marco, de=Mark, fr=Marc" },
    "wiki.loc.mirror.c.beh": { it: "Classe C: copia il valore da un campo sorgente a piu campi destinazione", en: "Class C: copies the value from a source field to multiple destination fields" },
    "wiki.loc.mirror.c.ex": { it: "Esempio: una bio scritta in IT viene copiata in tutti i campi bio delle altre lingue", en: "Example: an IT bio is copied to all other language bio fields" },
    "wiki.loc.hashtags.title": { it: "Traduzione Hashtag", en: "Hashtag Translation" },
    "wiki.loc.hashtags.p1": { it: "Gli hashtag possono essere tradotti automaticamente. L'editor mantiene il collegamento tra hashtag originali e tradotti.", en: "Hashtags can be automatically translated. The editor maintains the link between original and translated hashtags." },
    "wiki.loc.fig": { it: "Il pannello Localizzazione con le lingue disponibili.", en: "The Localization panel with available languages." },
    "wiki.loc.tip.title": { it: "Suggerimento", en: "Tip" },
    "wiki.loc.tip.text": { it: "Traduci prima in inglese (la lingua di riferimento) e poi nelle altre lingue. Le traduzioni da IT direttamente a DE o FR possono perdere sfumature.", en: "Translate first to English (the reference language) and then to other languages. Translations directly from IT to DE or FR may lose nuances." },

    "wiki.faq.title": { it: "FAQ - Domande Frequenti", en: "FAQ - Frequently Asked Questions" },
    "wiki.faq.q1.title": { it: "Posso usare Story Forge su Mac o Linux?", en: "Can I use Story Forge on Mac or Linux?" },
    "wiki.faq.q1.ans": { it: "Al momento Story Forge e disponibile solo per Windows 10/11 a 64 bit. Non ci sono piani immediati per Mac o Linux.", en: "Currently Story Forge is only available for Windows 10/11 64-bit. There are no immediate plans for Mac or Linux." },
    "wiki.faq.q2.title": { it: "Quante storie posso creare?", en: "How many stories can I create?" },
    "wiki.faq.q2.ans": { it: "Non c e limite. Puoi creare quanti progetti vuoi, ognuno con la propria storia e profili.", en: "There is no limit. You can create as many projects as you want, each with its own story and profiles." },
    "wiki.faq.q3.title": { it: "Posso collaborare con altri utenti?", en: "Can I collaborate with other users?" },
    "wiki.faq.q3.ans": { it: "Al momento la collaborazione avviene tramite condivisione di file .sfpkg. Non c e sincronizzazione in tempo reale.", en: "Currently collaboration happens through sharing .sfpkg files. There is no real-time synchronization." },
    "wiki.faq.q4.title": { it: "Il LLM e obbligatorio?", en: "Is the LLM mandatory?" },
    "wiki.faq.q4.ans": { it: "No. Puoi creare tutta la storia manualmente. Il LLM e uno strumento opzionale che facilita la generazione e traduzione del contenuto.", en: "No. You can create the entire story manually. The LLM is an optional tool that facilitates content generation and translation." },
    "wiki.faq.q5.title": { it: "Come condivido una storia con amici?", en: "How do I share a story with friends?" },
    "wiki.faq.q5.ans": { it: "Esporta il pacchetto .sfpkg e condividilo via WhatsApp, Telegram o email. L amico lo importa nell app Android toccando il file.", en: "Export the .sfpkg package and share it via WhatsApp, Telegram or email. Your friend imports it in the Android app by tapping the file." },
    "wiki.faq.q6.title": { it: "Posso modificare una storia gia esportata?", en: "Can I edit a story already exported?" },
    "wiki.faq.q6.ans": { it: "Si. Importa il file .sfpkg nella Dashboard, modifica e riesporta. La nuova versione sostituira la precedente.", en: "Yes. Import the .sfpkg file in the Dashboard, edit and re-export. The new version will replace the previous one." },

